SELECT DATE_FORMAT(signup_date, 'yyyy-MM') signup_month, SUM(credit_limit) total_credit_limit, COUNT(*) cnt, ROUND(SUM(credit_limit) * 100.0 / SUM(SUM(credit_limit)) OVER (), 2) AS pct_of_total FROM customers WHERE name LIKE '%Srisuk%' GROUP BY DATE_FORMAT(signup_date, 'yyyy-MM') ORDER BY signup_month LIMIT 10;
